const { cancelDriverRequest } = require("./actionCancelDriverRequest.service");
const {

  performJoinSelect,


} = require("../../CRUD/Read/ReadData");

const { createDriverRequest } = require("../../CRUD/Create/CreateData");
const { getUserByUserUniqueId, createUser } = require("../User.service");

const { sendSms } = require("../../Utils/smsSender");
const { createJourneyRoutePoint } = require("../JourneyRoutePoints.service");
const {
  getTariffRateByVehicleTypeUniqueId,
} = require("../TariffRateForVehicleTypes.service");
const { createJourneyDecision } = require("../JourneyDecisions.service");
const { currentDate } = require("../../Utils/CurrentDate");
const { createJourney } = require("../Journey");


const {
  journeyStatusMap,


} = require("../../Utils/ListOfSeedData");

const { executeInTransaction } = require("../../Utils/DatabaseTransaction");
const logger = require("../../Utils/logger");


const AppError = require("../../Utils/AppError");

/**
 * Allows driver to take goods from street and create a shipper request on behalf of shipper
 * This is used when drivers find shippers on the street and need to register the transport
 * @param {Object} body - Request body containing shipper and journey details
 * @param {Object} user - Driver user object from authentication
 * @returns {Promise<Object>} Response containing shipper, driver, journey, and decision data
 */
const takeFromStreet = async (body, user) => {
  try {
    // first verify if driver has active request
    const {
      verifyDriverJourneyStatus,
    } = require("./statusVerification");
    const driverStatus = await verifyDriverJourneyStatus({
      userUniqueId: user?.userUniqueId,
    });
    // console.log("@takeFromStreet driverStatus", driverStatus);

    // if driver has active request return the current status
    if (driverStatus) {
      const journeyStatusId = driverStatus?.driver?.driver?.journeyStatusId;
      // if driver accepted request return driverStatus
      if (journeyStatusId >= 3) {
        return driverStatus;
      } else if (journeyStatusId >= 1) {
        // if journeyStatusId is one or two, cancel current request
        const cancelResult = await cancelDriverRequest({
          ownerUserUniqueId: user.userUniqueId,
          user: user,
          roleId: user.roleId,
          cancellationReasonsTypeId: body.cancellationReasonsTypeId || 1, // Provide a default reason ID
        });

        // If cancellation failed, return the error
        if (cancelResult.message === "error") {
          throw new AppError(
            cancelResult.error || "Failed to cancel current request",
            400,
          );
        }

        // Wait a moment for the cancellation to process
        // await new Promise((resolve) => setTimeout(resolve, 500));
      }
    }
    // if there is no active request create new shipper and shipper request and link with driver request and create journey decision and journey

    const journeyStatusId = journeyStatusMap.journeyStarted;
    const userUniqueId = user?.userUniqueId;
    const randNumber = Math.floor(Math.random() * 100000000);
    const requestedFrom = "street";
    const phoneNumber = body?.phoneNumber;
    const data = {
      shipperRequestBatchId: body.shipperRequestBatchId,
      phoneNumber,
      requestedFrom,
      fullName: null,
      email: `fakeEmail_${randNumber}@shipper.com`,
      roleId: 1,
      statusId: 1,
      userRoleStatusDescription: "this is shipper",
    };
    const responseData = {
      shipper: null,
      driver: null,
      journey: null,
      decision: null,
    };

    // ✅ Wrap user creation + all database operations in transaction for full atomicity
    // User creation now happens INSIDE transaction (if needed)
    // This ensures user creation + shipper request + driver request + journey decision + journey + route points are all atomic
    // All operations must succeed together or all fail together (prevents orphaned records)
    let userShipper,
      shipperRequest,
      driverRequest,
      journeyDecision,
      journeyServices,
      targetRequest;

    await executeInTransaction(
      async (connection) => {
        // Create shipper user INSIDE transaction (with connection for transaction support)
        // This ensures if request creation fails, user creation is rolled back (no orphaned users)
        userShipper = await createUser({ ...body, ...data }, connection);

        if (userShipper.message === "error") {
          throw new Error(
            userShipper.error || "Unable to create user data to ship goods",
          );
        }

        const dataOfShipper = userShipper?.data;
        if (!dataOfShipper?.userUniqueId) {
          throw new Error("Failed to get userUniqueId from created user");
        }

        // Create shipper request (with connection for transaction support)
        const { createShipperRequest } = require("../ShipperRequest");
        shipperRequest = await createShipperRequest(
          {
            ...body,
            userUniqueId: dataOfShipper.userUniqueId, // Set shipper's userUniqueId after creating shipper user
            // shipperRequestCreatedBy and shipperRequestCreatedByRoleId are already in body from controller
          },
          journeyStatusId, // journeyStarted (5) - driver already picked up goods from street
          connection, // ✅ Pass connection for transaction support
        );

        // Validate shipper request creation
        // Service returns array when driver role (2), or error object on failure
        if (
          !shipperRequest ||
          (!Array.isArray(shipperRequest) &&
            shipperRequest.message === "error") ||
          (Array.isArray(shipperRequest) && shipperRequest.length === 0)
        ) {
          throw new Error(
            Array.isArray(shipperRequest)
              ? "Failed to create shipper request (empty array)"
              : shipperRequest?.error || "Failed to create shipper request",
          );
        }

        targetRequest = Array.isArray(shipperRequest)
          ? shipperRequest[0]
          : null;
        if (!targetRequest) {
          throw new Error("Failed to extract shipper request from result");
        }

        // Create driver request (with connection for transaction support)
        driverRequest = await createDriverRequest(
          body,
          userUniqueId,
          journeyStatusId,
          connection, // ✅ Pass connection for transaction support
        );

        // Validate driver request
        if (!driverRequest?.data?.[0]) {
          throw new Error("Failed to create driver request");
        }

        // Create journey decision (with connection for transaction support)
        const {
          shippingDate: shippingDateByDriver,
          deliveryDate: deliveryDateByDriver,
          shippingCost: shippingCostByDriver,
        } = body;
        const decisionData = {
          shipperRequestId: targetRequest.shipperRequestId,
          driverRequestId: driverRequest.data[0].driverRequestId,
          journeyStatusId,
          decisionTime: currentDate(),
          decisionBy: "driver",
          shippingDateByDriver,
          deliveryDateByDriver,
          shippingCostByDriver,
          journeyDecisionCreatedBy: userUniqueId,
        };

        journeyDecision = await createJourneyDecision(
          decisionData,
          connection, // ✅ Pass connection for transaction support
        );

        // Validate journey decision
        if (journeyDecision?.message === "error") {
          throw new Error(
            journeyDecision.error || "Failed to create journey decision",
          );
        }

        // Create journey (with connection for transaction support)
        const journeyDecisionUniqueId =
          journeyDecision.data[0].journeyDecisionUniqueId;
        const journeyData = {
          journeyDecisionUniqueId,
          startTime: currentDate(),
          endTime: currentDate(),
          fare: 0,
          journeyStatusId,
          journeyCreatedBy: userUniqueId,
        };

        journeyServices = await createJourney(
          journeyData,
          connection, // ✅ Pass connection for transaction support
        );

        // Validate journey
        if (!journeyServices?.data?.[0]) {
          throw new Error("Failed to create journey");
        }

        // Create journey route points (with connection for transaction support)
        const originLocation = body.originLocation;
        const JourneyPoints = await createJourneyRoutePoint(
          {
            journeyDecisionUniqueId:
              journeyDecision.data[0].journeyDecisionUniqueId,
            latitude: originLocation.latitude,
            longitude: originLocation.longitude,
            userUniqueId: userUniqueId,
          },
          connection, // ✅ Pass connection for transaction support
        );

        // Store decision and journey in responseData for later use
        responseData.decision = journeyDecision.data[0];
        responseData.journey = journeyServices.data[0];
      },
      {
        timeout: 30000, // 30 seconds - enough for user creation + all database operations
        logging: true,
      },
    );

    // After transaction commits successfully, send SMS and fetch read-only data (outside transaction)
    // SMS is external service and shouldn't be part of transaction
    if (phoneNumber) {
      const driverName = user?.fullName || "Driver";
      const itemName = body?.shippableItemName || "your items";
      const welcomeMessage = `Hello! Your transport of ${itemName} with ${driverName} has been registered and started. Thank you for using our transport service. Have a safe journey!`;
      try {
        await sendSms(phoneNumber, null, welcomeMessage);
      } catch (smsError) {
        // Don't fail the request if SMS fails, just log the error
        logger.warn("Failed to send SMS in takeFromStreet", {
          phoneNumber,
          error: smsError.message,
        });
      }
    }

    // Fetch read-only data (outside transaction)
    // This follows the pattern: "Read BEFORE transaction, Write INSIDE transaction, Read AFTER transaction"
    // fetch vehicle joined with ownership and types for the driver
    const vehicleRows = await performJoinSelect({
      baseTable: "Vehicle",
      joins: [
        {
          table: "VehicleOwnership",
          on: "VehicleOwnership.vehicleUniqueId = Vehicle.vehicleUniqueId",
        },
        {
          table: "VehicleTypes",
          on: "Vehicle.vehicleTypeUniqueId = VehicleTypes.vehicleTypeUniqueId",
        },
      ],
      conditions: {
        "VehicleOwnership.userUniqueId": userUniqueId,
      },
      limit: 1,
    });
    const vehicleTypeUniqueId = vehicleRows?.[0]?.vehicleTypeUniqueId;
    const vehicleTariffRate =
      await getTariffRateByVehicleTypeUniqueId(vehicleTypeUniqueId);
    const driver = await getUserByUserUniqueId(userUniqueId);
    const driverData = {
      driver: { ...driver.data, ...driverRequest.data[0] },
      vehicle: vehicleRows?.[0],
      vehicleTariffRate: vehicleTariffRate.data[0],
    };
    responseData.shipper = {
      ...userShipper?.dataOfShipper,
      ...targetRequest,
    };
    responseData.driver = driverData;
    responseData.status = journeyStatusId;
    return responseData;
  } catch (error) {
    // Log error with context for debugging
    logger.error("Error in takeFromStreet", {
      message: error.message,
      stack: error.stack,
      name: error.name,
      userUniqueId: user?.userUniqueId,
      body: {
        phoneNumber: body?.phoneNumber,
        shipperRequestBatchId: body?.shipperRequestBatchId,
        shippableItemName: body?.shippableItemName,
      },
    });
    throw new AppError(
      error.message || "Unable to create request",
      error.statusCode || 500,
    );
  }
};
module.exports = { takeFromStreet };

"use strict";

const {
  db
} = require("../../CompanyHelper.service");

/**
 * ### Atomically cancel an entire company-targeted freight batch.
 *
 * **What is updated in one DB transaction:**
 *
 * | Table                          | What changes                                                  |
 * |-------------------------------|---------------------------------------------------------------|
 * | ShipperRequestBatch          | journeyStatusId → 7 (cancelledByShipper) or 10 (Admin)      |
 * | ShipperRequest               | All rows in this batch → same cancelled status                |
 * | JourneyDecisions               | All open decisions for those requests → same cancelled status |
 * | DriverRequest                  | Matched drivers released back to waiting (status 1)           |
 * | CompanyBidRequest              | All submitted bids → 'expired'                                |
 * | CompanyBidVehicleAssignment    | All assignments → 'cancelled'                                 |
 *
 * **Why this approach?**
 * Sending N individual HTTP cancel calls from the client is wasteful and risks
 * partial failure.  One atomic transaction guarantees either everything cancels
 * or nothing does.
 *
 * **Junior Note — terminal statuses guard:**
 * `journeyStatusId NOT IN (7,9,10,12)` prevents re-cancelling rows that are
 * already in a terminal state (e.g. a driver independently cancelled their side).
 *
 * @param {string} batchUniqueId            - UUID of the batch to cancel.
 * @param {string} userUniqueId             - Authenticated user's UUID.
 * @param {number} roleId                   - Authenticated user's role ID.
 * @param {number|null} cancellationReasonsTypeId - Optional reason FK.
 */

const cancelBatch = async ({
  batchUniqueId,
  userUniqueId,
  roleId,
  cancellationReasonsTypeId
}) => {
  if (!batchUniqueId || !userUniqueId) {
    throw new AppError("batchUniqueId and userUniqueId are required", 400);
  }

  // 1a. Validate cancellation reason is appropriate for company context
  await assertCompanyCancellationReason(cancellationReasonsTypeId);

  // 1b. Verify batch exists + ownership
  const batch = await findOne("ShipperRequestBatch", {
    batchUniqueId
  }, "Batch not found");
  const isAdmin = roleId === 3 || roleId === 6; // admin / super-admin

  if (batch.shipperUserUniqueId !== userUniqueId && !isAdmin) {
    throw new AppError("Unauthorized: batch does not belong to you", 403);
  }
  const terminalStatuses = [journeyStatusMap.cancelledByShipper,
  // 7
    journeyStatusMap.cancelledByDriver,
    // 9
    journeyStatusMap.cancelledByAdmin,
    // 10
    journeyStatusMap.cancelledBySystem // 12
  ].filter(Boolean); // remove undefined if any key is missing

  if (terminalStatuses.includes(batch.journeyStatusId)) {
    throw new AppError("Batch is already cancelled", 400);
  }
  const cancelStatusId = isAdmin ? journeyStatusMap.cancelledByAdmin // 10
    : journeyStatusMap.cancelledByShipper; // 7

  const now = currentDate();

  // ── PLAN B: Smart auto-filter ─────────────────────────────────────────────
  // Slots in these statuses are LOCKED — they cannot be cancelled:
  //   5 = journeyStarted  (driver is actively on the road)
  //   6 = journeyCompleted (already delivered)
  //   + the terminal cancel statuses (already cancelled by anyone)
  const lockedStatuses = [journeyStatusMap.journeyStarted,
  // 5
    journeyStatusMap.journeyCompleted,
    // 6
    ...terminalStatuses // 7, 9, 10, 12
  ].filter(Boolean);
  const lockedClause = lockedStatuses.join(","); // e.g. "5,6,7,9,10,12"

  // Count all slots, locked slots, and cancellable slots in one query
  const [[slotSummary]] = await db().query(`SELECT
       COUNT(*)                                                          AS totalSlots,
       SUM(journeyStatusId IN (${lockedClause}))                        AS lockedSlots,
       SUM(journeyStatusId NOT IN (${lockedClause}))                    AS cancellableSlots,
       SUM(journeyStatusId IN (?,?))                                    AS inProgressSlots
     FROM ShipperRequest
     WHERE shipperRequestBatchId = ?
       AND shipperRequestDeletedAt IS NULL`, [journeyStatusMap.journeyStarted,
  // 5
    journeyStatusMap.journeyCompleted,
    // 6
    batchUniqueId]);
  const cancellableSlots = Number(slotSummary.cancellableSlots) || 0;
  const lockedSlots = Number(slotSummary.lockedSlots) || 0;
  const totalSlots = Number(slotSummary.totalSlots) || 0;

  // ── Slot-free batch (waiting / requested stage) ─────----──────────────────────
  // No ShipperRequest rows exist yet — bid hasn't been accepted.
  // Cancel the batch header and expire any open bids; nothing else to do.
  if (totalSlots === 0) {
    await Promise.all([db().query(`UPDATE ShipperRequestBatch
            SET journeyStatusId = ?,
                batchUpdatedAt  = ?
          WHERE batchUniqueId = ?`, [cancelStatusId, now, batchUniqueId]), db().query(`UPDATE CompanyBidRequest
            SET bidStatus = 'expired',
                isCancellationSeenByCompany = 'not seen by company yet'
          WHERE shipperRequestBatchId = ?
            AND bidStatus NOT IN ('expired','rejected_by_shipper','cancelled_by_company')`, [batchUniqueId])]);
    return {
      message: "Batch cancelled successfully",
      batchUniqueId
    };
  }

  // ── All existing slots are locked (started / completed / already cancelled) ─
  if (cancellableSlots === 0) {
    throw new AppError(`Cannot fully cancel this batch — all ${lockedSlots} slot(s) are either ` + `in transit (journeyStarted) or already completed/cancelled. ` + `No cancellable slots remain.`, 400);
  }

  // Determine the final batch-level status:
  //   - Any locked slots exist → batch becomes partiallyCancelled (17)
  //     because those slots remain alive (started/completed)
  //   - All slots are cancellable → batch becomes fully cancelled
  const finalBatchStatus = lockedSlots > 0 ? journeyStatusMap.partiallyCancelled // 17
    : cancelStatusId;

  // ── Steps 2–7: All UPDATEs run in parallel inside the transaction.
  //    Every ShipperRequest UPDATE now skips locked slots (started/completed).
  //    If ANY query rejects → executeInTransaction rolls back automatically.
  await Promise.all([
  // 2. Update the batch header with the correct final status
    db().query(`UPDATE ShipperRequestBatch
          SET journeyStatusId = ?,
              batchUpdatedAt  = ?
        WHERE batchUniqueId = ?`, [finalBatchStatus, now, batchUniqueId]),
    // 3. Cancel only the cancellable ShipperRequest slots — skip locked ones
    db().query(`UPDATE ShipperRequest
          SET journeyStatusId = ?
        WHERE shipperRequestBatchId = ?
          AND journeyStatusId NOT IN (${lockedClause})`, [cancelStatusId, batchUniqueId]),
    // 4. Cancel open JourneyDecisions linked to cancellable slots only
    db().query(`UPDATE JourneyDecisions jd
         INNER JOIN ShipperRequest pr
                 ON jd.shipperRequestId = pr.shipperRequestId
          SET jd.journeyStatusId = ?
        WHERE pr.shipperRequestBatchId = ?
          AND pr.journeyStatusId NOT IN (${lockedClause})
          AND jd.journeyStatusId NOT IN (${lockedClause})`, [cancelStatusId, batchUniqueId]),
    // 5. Release DriverRequest rows linked to cancellable slots back to waiting.
    //    Drivers on journeyStarted/journeyCompleted slots are NOT touched.
    db().query(`UPDATE DriverRequest dr
         INNER JOIN JourneyDecisions jd
                 ON dr.driverRequestId = jd.driverRequestId
         INNER JOIN ShipperRequest pr
                 ON jd.shipperRequestId = pr.shipperRequestId
          SET dr.journeyStatusId = ?
        WHERE pr.shipperRequestBatchId = ?
          AND pr.journeyStatusId NOT IN (${lockedClause})
          AND dr.journeyStatusId IN (1,2,3,4)`, [cancelStatusId, batchUniqueId]),
    // 6. Expire CompanyBidRequest offers for this batch.
    //    Always mark all bids regardless of slot status so companies are notified.
    db().query(`UPDATE CompanyBidRequest
          SET bidStatus = 'cancelled_by_company',
              isCancellationSeenByCompany = 'not seen by company yet'
        WHERE shipperRequestBatchId = ?`, [batchUniqueId]),
    // 7. Cancel vehicle assignments only for the cancellable slots
    db().query(`UPDATE CompanyBidVehicleAssignment cba
         INNER JOIN ShipperRequest pr
                 ON cba.shipperRequestUniqueId = pr.shipperRequestUniqueId
          SET cba.assignmentStatus    = 'cancelled_by_shipper',
              cba.assignmentUpdatedAt = ?
        WHERE pr.shipperRequestBatchId = ?
          AND pr.journeyStatusId NOT IN (${lockedClause})
          AND cba.assignmentStatus IN ('assigned', 'reassigned')`, [now, batchUniqueId])]);

  // 8. Register one CanceledJourneys audit record for the batch.
  //    contextId must be the integer batchId — the contextId column is INT.
  //    Uses contextType 'ShipperRequestBatch' so it is separate from
  //    per-vehicle ShipperRequest cancellation records.
  //    Duplicate guard: only insert if no record exists yet.
  const existingBatchCancel = await getData({
    tableName: "CanceledJourneys",
    conditions: {
      contextId: batch.batchId,
      contextType: "ShipperRequestBatch"
    }
  });
  if (existingBatchCancel.length === 0) {
    await createCanceledJourney({
      canceledBy: userUniqueId,
      canceledTime: now,
      contextId: batch.batchId,
      contextType: "ShipperRequestBatch",
      cancellationReasonsTypeId: cancellationReasonsTypeId || null,
      roleId,
      shipperUserUniqueId: batch.shipperUserUniqueId
    });
  }

  // ── Collect notification targets in parallel (reads only) ─────────────────
  // Fired AFTER all writes succeed but still inside the transaction so reads
  // see the committed state.  Notifications are sent by the controller AFTER
  // the transaction commits to avoid holding DB locks during I/O.
  const [[companyRows], [driverRows], [shipperRows]] = await Promise.all([
  // Companies that had bids on this batch
    db().query(`SELECT DISTINCT companyUniqueId
         FROM CompanyBidRequest
        WHERE shipperRequestBatchId = ?`, [batchUniqueId]),
    // Drivers who had a JourneyDecision linked to this batch
    db().query(`SELECT DISTINCT u.phoneNumber, u.userUniqueId, dr.driverRequestId
         FROM DriverRequest dr
         INNER JOIN JourneyDecisions jd
                 ON dr.driverRequestId = jd.driverRequestId
         INNER JOIN ShipperRequest pr
                 ON jd.shipperRequestId = pr.shipperRequestId
         INNER JOIN Users u
                 ON dr.userUniqueId = u.userUniqueId
        WHERE pr.shipperRequestBatchId = ?`, [batchUniqueId]),
    // Shipper who owns the batch — for real-time confirmation on other devices
    db().query(`SELECT u.phoneNumber, u.userUniqueId
         FROM Users u
        WHERE u.userUniqueId = ?
        LIMIT 1`, [batch.shipperUserUniqueId])]);
  return {
    message: "success",
    data: {
      batchUniqueId,
      finalBatchStatus,
      cancelledStatus: cancelStatusId,
      cancellationReasonsTypeId: cancellationReasonsTypeId || null,
      // Plan B summary — tells the client exactly what happened
      slotSummary: {
        total: Number(slotSummary.totalSlots) || 0,
        cancelled: cancellableSlots,
        skipped: lockedSlots,
        skippedReason: inProgressSlots > 0 ? "Some slots are in transit (journeyStarted) or already completed — they were left untouched." : null
      }
    },
    // ── Internal use only — stripped before HTTP response ──────────────────
    _notificationTargets: {
      companies: companyRows.map(r => r.companyUniqueId),
      drivers: driverRows,
      shipper: shipperRows[0] || null,
      cancelStatusId,
      batchUniqueId
    }
  };
};

module.exports = {
  cancelBatch
};


const AppError = require("../../../Utils/AppError");
const { assertCompanyCancellationReason } = require("../../CanceledJourneys/cancelHelper.service");
const { journeyStatusMap } = require("../../../Utils/ListOfSeedData");
const { currentDate } = require("../../../Utils/CurrentDate");
const { getData } = require("../../../CRUD/Read/ReadData");
const { createCanceledJourney } = require("../../CanceledJourneys/cancelCreate.service");

"use strict";

const {
  db
} = require("../../CompanyHelper.service");

/**
 * ### Atomically cancel an entire company-targeted freight batch.
 *
 * **What is updated in one DB transaction:**
 *
 * | Table                          | What changes                                                  |
 * |-------------------------------|---------------------------------------------------------------|
 * | ShipperRequestBatch          | journeyStatusId → 7 (cancelledByShipper) or 10 (Admin)      |
 * | ShipperRequest               | All rows in this batch → same cancelled status                |
 * | JourneyDecisions               | All open decisions for those requests → same cancelled status |
 * | DriverRequest                  | Matched drivers released back to waiting (status 1)           |
 * | CompanyBidRequest              | All submitted bids → 'expired'                                |
 * | CompanyBidVehicleAssignment    | All assignments → 'cancelled'                                 |
 *
 * **Why this approach?**
 * Sending N individual HTTP cancel calls from the client is wasteful and risks
 * partial failure.  One atomic transaction guarantees either everything cancels
 * or nothing does.
 *
 * **Junior Note — terminal statuses guard:**
 * `journeyStatusId NOT IN (7,9,10,12)` prevents re-cancelling rows that are
 * already in a terminal state (e.g. a driver independently cancelled their side).
 *
 * @param {string} batchUniqueId            - UUID of the batch to cancel.
 * @param {string} userUniqueId             - Authenticated user's UUID.
 * @param {number} roleId                   - Authenticated user's role ID.
 * @param {number|null} cancellationReasonsTypeId - Optional reason FK.
 */

const partialCancelBatch = async ({
  batchUniqueId,
  userUniqueId,
  roleId,
  slotIds,
  cancellationReasonsTypeId
}) => {
  if (!batchUniqueId || !userUniqueId || !slotIds?.length) {
    throw new AppError("batchUniqueId, userUniqueId and slotIds are required", 400);
  }

  // 1a. Validate cancellation reason is appropriate for company context
  await assertCompanyCancellationReason(cancellationReasonsTypeId);

  // 1b. Verify batch exists + ownership
  const batch = await findOne("ShipperRequestBatch", {
    batchUniqueId
  }, "Batch not found");
  const isAdmin = roleId === 3 || roleId === 6;
  if (batch.shipperUserUniqueId !== userUniqueId && !isAdmin) {
    throw new AppError("Unauthorized: batch does not belong to you", 403);
  }

  // 2. Batch-level terminal guard
  const batchTerminal = [journeyStatusMap.cancelledByShipper,
  // 7
    journeyStatusMap.cancelledByAdmin,
    // 10
    journeyStatusMap.cancelledBySystem // 12
  ].filter(Boolean);
  if (batchTerminal.includes(batch.journeyStatusId)) {
    throw new AppError("Batch is already fully cancelled", 400);
  }

  // 3. Fetch the requested slots and verify they all belong to this batch
  const placeholders = slotIds.map(() => "?").join(",");
  const [slots] = await db().query(`SELECT shipperRequestUniqueId, shipperRequestId, journeyStatusId
       FROM ShipperRequest
      WHERE shipperRequestUniqueId IN (${placeholders})
        AND shipperRequestBatchId = ?
        AND shipperRequestDeletedAt IS NULL`, [...slotIds, batchUniqueId]);
  if (slots.length !== slotIds.length) {
    throw new AppError("One or more slotIds do not belong to this batch or do not exist", 400);
  }

  // 4. Validate cancellability — reject if any slot is not cancellable
  const CANCELLABLE = new Set([journeyStatusMap.waiting,
  // 1
    journeyStatusMap.requested,
    // 2
    journeyStatusMap.acceptedByDriver,
    // 3
    journeyStatusMap.acceptedByShipper // 4
  ]);
  const notCancellable = slots.filter(s => !CANCELLABLE.has(s.journeyStatusId));
  if (notCancellable.length > 0) {
    throw new AppError(`The following slots cannot be cancelled (already in transit or terminal): ` + notCancellable.map(s => s.shipperRequestUniqueId).join(", "), 400);
  }
  const cancelStatusId = isAdmin ? journeyStatusMap.cancelledByAdmin : journeyStatusMap.cancelledByShipper;
  const now = currentDate();
  const inClause = [journeyStatusMap.cancelledByShipper, journeyStatusMap.cancelledByDriver, journeyStatusMap.cancelledByAdmin, journeyStatusMap.cancelledBySystem].join(",");

  // 5. Cancel only the specified slots atomically
  await Promise.all([
  // Cancel ShipperRequest rows
    db().query(`UPDATE ShipperRequest
          SET journeyStatusId = ?
        WHERE shipperRequestUniqueId IN (${placeholders})
          AND journeyStatusId NOT IN (${inClause})`, [cancelStatusId, ...slotIds]),
    // Cancel open JourneyDecisions for those slots
    db().query(`UPDATE JourneyDecisions jd
         INNER JOIN ShipperRequest pr
                 ON jd.shipperRequestId = pr.shipperRequestId
          SET jd.journeyStatusId = ?
        WHERE pr.shipperRequestUniqueId IN (${placeholders})
          AND jd.journeyStatusId NOT IN (${inClause})`, [cancelStatusId, ...slotIds]),
    // Release DriverRequest rows linked to those slots
    db().query(`UPDATE DriverRequest dr
         INNER JOIN JourneyDecisions jd
                 ON dr.driverRequestId = jd.driverRequestId
         INNER JOIN ShipperRequest pr
                 ON jd.shipperRequestId = pr.shipperRequestId
          SET dr.journeyStatusId = ?
        WHERE pr.shipperRequestUniqueId IN (${placeholders})
          AND dr.journeyStatusId IN (1,2,3,4)`, [cancelStatusId, ...slotIds]),
    // Cancel vehicle assignments for those slots
    db().query(`UPDATE CompanyBidVehicleAssignment cba
         INNER JOIN ShipperRequest pr
                 ON cba.shipperRequestUniqueId = pr.shipperRequestUniqueId
          SET cba.assignmentStatus    = 'cancelled_by_shipper',
              cba.assignmentUpdatedAt = ?
        WHERE pr.shipperRequestUniqueId IN (${placeholders})
          AND cba.assignmentStatus IN ('assigned', 'reassigned')`, [now, ...slotIds])]);

  // 6. Determine new batch-level status
  //    Count how many slots are still active (not in a terminal state)
  const [remaining] = await db().query(`SELECT COUNT(*) AS activeCount
       FROM ShipperRequest
      WHERE shipperRequestBatchId = ?
        AND journeyStatusId NOT IN (${inClause})
        AND shipperRequestDeletedAt IS NULL`, [batchUniqueId]);
  const activeCount = remaining[0]?.activeCount ?? 0;
  const newBatchStatus = activeCount === 0 ? cancelStatusId // fully cancelled
    : journeyStatusMap.partiallyCancelled; // 17 — still has active slots

  await db().query(`UPDATE ShipperRequestBatch
        SET journeyStatusId = ?, batchUpdatedAt = ?
      WHERE batchUniqueId = ?`, [newBatchStatus, now, batchUniqueId]);

  // 7. Audit record per cancelled slot
  for (const slot of slots) {
    const existingCancel = await getData({
      tableName: "CanceledJourneys",
      conditions: {
        contextId: slot.shipperRequestId,
        contextType: "ShipperRequest"
      }
    });
    if (existingCancel.length === 0) {
      await createCanceledJourney({
        canceledBy: userUniqueId,
        canceledTime: now,
        contextId: slot.shipperRequestId,
        contextType: "ShipperRequest",
        cancellationReasonsTypeId: cancellationReasonsTypeId || null,
        roleId,
        shipperUserUniqueId: batch.shipperUserUniqueId
      });
    }
  }

  // 8. Collect notification targets
  const [[driverRows], [shipperRows]] = await Promise.all([db().query(`SELECT DISTINCT u.phoneNumber, u.userUniqueId
         FROM DriverRequest dr
         INNER JOIN JourneyDecisions jd ON dr.driverRequestId = jd.driverRequestId
         INNER JOIN ShipperRequest pr   ON jd.shipperRequestId = pr.shipperRequestId
         INNER JOIN Users u             ON dr.userUniqueId = u.userUniqueId
        WHERE pr.shipperRequestUniqueId IN (${placeholders})`, [...slotIds]), db().query(`SELECT u.phoneNumber, u.userUniqueId
         FROM Users u WHERE u.userUniqueId = ? LIMIT 1`, [batch.shipperUserUniqueId])]);
  return {
    message: "success",
    data: {
      batchUniqueId,
      cancelledSlots: slotIds.length,
      remainingActiveSlots: activeCount,
      newBatchStatus,
      cancellationReasonsTypeId: cancellationReasonsTypeId || null
    },
    _notificationTargets: {
      drivers: driverRows,
      shipper: shipperRows[0] || null,
      cancelStatusId,
      batchUniqueId
    }
  };
};

